#[derive(Debug, Clone)]
pub struct Interval {
    pub min: f64,
    pub max: f64,
}

impl Interval {
    /// Creates a new interval [min, max].
    /// Panics if min >= max.
    pub fn new(min: f64, max: f64) -> Self {
        assert!(
            min < max,
            "Invalid interval: min ({}) must be less than max ({})",
            min,
            max
        );
        Interval { min, max }
    }
}

#[derive(Debug, Clone)]
pub struct ChebyshevPoly {
    /// Polynomial coefficients in increasing degree order
    pub coef: Vec<i32>,
    /// Domain interval, must satisfy domain.min < domain.max
    pub domain: Interval,
    /// Window interval, must satisfy window.min < window.max
    pub window: Interval,
}

/// Constructs a Chebyshev polynomial descriptor from a non-empty list of i8 coefficients.
/// 
/// The resulting `ChebyshevPoly` has:
/// 1) `coef` converted to `i32` with the same order and length,
/// 2) a default domain of [-1.0, 1.0],
/// 3) a default window of [-1.0, 1.0].
///
/// Panics if `coef` is empty.
pub fn chebyshev(coef: Vec<i8>) -> ChebyshevPoly {
    assert!(!coef.is_empty(), "Coefficient list must be non-empty");
    let coef_i32: Vec<i32> = coef.into_iter().map(|c| c as i32).collect();
    let domain = Interval::new(-1.0, 1.0);
    let window = Interval::new(-1.0, 1.0);
    ChebyshevPoly {
        coef: coef_i32,
        domain,
        window,
    }
}

